package com.nextgen.gameaggregator.vendor.api.pragmaticplay.v1_180.promowin;

import com.nextgen.gameaggregator.grpc.v1.operator.betresult.BetResultGrpcVo;
import com.nextgen.gameaggregator.vendor.api.pragmaticplay.component.action.AbstractAction;
import com.nextgen.gameaggregator.vendor.api.pragmaticplay.component.constant.Constant;
import com.nextgen.gameaggregator.vendor.api.pragmaticplay.component.constant.ConstantErrorMessage;
import com.nextgen.gameaggregator.vendor.component.vendor.VendorAdaptor;
import com.nextgen.gameaggregator.vendor.data.mariadb.reader.entity.VendorPlayerReader;
import com.nextgen.gameaggregator.vendor.data.mariadb.reader.manager.VendorPlayerReaderManager;
import com.nextgen.gameaggregator.vendor.grpc.v1.subcriber.OperatorBetResultGrpc;
import com.nextgen.sas.core.web.wrapper.WebRequestWrapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

import static com.nextgen.gameaggregator.vendor.api.pragmaticplay.component.constant.Constant.VENDOR_CODE;

@RestController
@RequestMapping(path = Constant.WEB_ACTION, consumes = {MediaType.APPLICATION_FORM_URLENCODED_VALUE})
public class PromoWinAction extends AbstractAction {

    @Autowired
    private OperatorBetResultGrpc operatorBetResultGrpc;
    @Autowired
    private VendorAdaptor vendorAdaptor;

    VendorPlayerReader vendorPlayerReader;

    @Autowired
    VendorPlayerReaderManager vendorPlayerReaderManager;

    private static final Logger logger = LoggerFactory.getLogger(VendorAdaptor.class);

    @PostMapping(path = Constant.ACTION_PROMO_WIN)
    public PromoWinActionVo promoWin(PromoWinActionDto dto, WebRequestWrapper request) {

        //token generated by random uuid first, to be confirmed...
        String traceId = UUID.randomUUID().toString();
        HashMap<String, Object> formattedOutput = new HashMap<String, Object>();
        HashMap<String,Object> promoWinOutput =new HashMap<String,Object>();

        //* Temporary solution to map into DTO
        dto = this.queryStringToDto(request.getBody(), PromoWinActionDto.class);
        PromoWinActionVo thisVo = new PromoWinActionVo();
        thisVo.setTraceId(traceId);

        //* DTO Validation
        Map<String, String> dtoValidationResult = this.doValidation(dto, PromoWinActionDto.class);
        //* Verify validation result
        thisVo.verifyValidationResultAndManipulateErrorAndDescription(dtoValidationResult);

        //region create result log for all request that comes to result end point
        Long aggregatorRequestStartMs = Instant.now().toEpochMilli();
        String playerToken = (dto.getToken() == null)?"_NULL": "_"+dto.getToken();
        this.createSeamlessResultLogRecord(VENDOR_CODE+"_promoWin_"+aggregatorRequestStartMs+playerToken, aggregatorRequestStartMs,
                request.getBody());
        //endregion

        //check if all vendor requested dto param is fit
        if (thisVo.getError() == ConstantErrorMessage.CODE_SUCCESS) {
            if(dto.getUserId() != null){
                vendorPlayerReader = vendorPlayerReaderManager.findByVendorUsername(dto.getUserId());
            } else {
                vendorPlayerReader = null;
            }

            //check player authentication
            if (vendorPlayerReader != null) {
                //prepare for default error response
                thisVo.setErrorAndDescriptionByConstantResponseKey(ConstantErrorMessage.RESPONSE_KEY_INTERNAL_SERVER_ERROR_RECONCILIATION);
                formattedOutput = this.handleQueryStringDataToMapObject(request.getBody());
                formattedOutput.put("rawRequest", request.getBody());
                formattedOutput.put("vendorPlayerReader", vendorPlayerReader);

                //check is the vendor class file availability
                if (vendorAdaptor.getVendor(vendorPlayerReader.getVendorId(), 1,
                        vendorPlayerReader.getVendorCredentialId())) {

                    //call class file to process bet data
                    promoWinOutput = vendorAdaptor.seamlessVendor.promoWin(formattedOutput);

                    //check is the class file process data success?
                    if((int)promoWinOutput.get("error") == 0){
                        try{
                            //assign default success data
                            thisVo.setCurrency(vendorPlayerReader.getCurrencyCode());
                            thisVo.setTraceId(traceId);
                            thisVo.setBonus(BigDecimal.valueOf(0d));
                            thisVo.setTransactionId(traceId.replace("-", ""));

                            System.out.println("promoWin BEFORE GRPC traceId ::::::" + traceId);

                            //prepare call to operator grpc
                            BetResultGrpcVo serviceVo = this.operatorBetResultGrpc.betResult(
                                    Long.parseLong(promoWinOutput.get("agentId").toString()),
                                    Long.parseLong(promoWinOutput.get("agentPlayerId").toString()),
                                    Long.parseLong(promoWinOutput.get("gameId").toString()),
                                    vendorPlayerReader.getCurrencyCode(),
                                    traceId,
                                    this.findAgentCredentialIdByAgentId(Long.parseLong(promoWinOutput.get("agentId").toString())),
                                    promoWinOutput.get("betHistoryId").toString(),
                                    dto.getReference(),
                                    dto.getRoundId(),
                                    Double.parseDouble(promoWinOutput.get("betAmount").toString()),
                                    Double.parseDouble(promoWinOutput.get("winLoss").toString()),
                                    Integer.parseInt(promoWinOutput.get("resultType").toString()),
                                    Long.parseLong(promoWinOutput.get("betTime").toString()),
                                    dto.getTimestamp()
                            );

                            System.out.println("promoWin AFTER GRPC traceId ::::::" + traceId);
                            System.out.println("promoWin serviceVo ::::::" + serviceVo);

                            //check grpc status
                            if(serviceVo.getStatus()){
                                //if grpc success, set as success and set the responding balance amount
                                thisVo.setErrorAndDescriptionByConstantResponseKey(ConstantErrorMessage.RESPONSE_KEY_SUCCESS);
                                thisVo.setCash((BigDecimal.valueOf(serviceVo.getBalance())).setScale(2, RoundingMode.HALF_DOWN));
                            }
                        } catch (Exception e){
                            //return 100 error which required vendor resend us request
                            logger.error("promoWin grpc error : " + e);
                        }
                    } else {
                        // if insert bet data got issue
                        // logged in class file already
                    }
                } else {
                    // if class file is not found
                    thisVo.setErrorAndDescriptionByConstantResponseKey(ConstantErrorMessage.RESPONSE_KEY_INTERNAL_SERVER_ERROR);
                }
            } else {
                //if auth fail
                thisVo.setErrorAndDescriptionByConstantResponseKey(ConstantErrorMessage.RESPONSE_KEY_PLAYER_AUTH_FAILED);
            }
        }

        System.out.println("promoWin traceId ::::::" + traceId);
        System.out.println("promoWin thisVo ::::::" + thisVo);

        if (thisVo.getError() != 0){
            //region create ERROR log for all request that if error not = 0
            Long aggregatorRequestStartMsErr = Instant.now().toEpochMilli();
            String playerTokenErr = (dto.getToken() == null)?"_NULL": "_"+dto.getToken();
            this.createSeamlessResultLogRecord(VENDOR_CODE+"_promoWinErr_"+aggregatorRequestStartMsErr+playerTokenErr, aggregatorRequestStartMsErr,
                    request.getBody()+"||"+thisVo+"||"+formattedOutput+"||"+promoWinOutput);
            //endregion
        }

        return thisVo;
    }
}
